/* Minimal stub for web-vitals – provides async functions returning random values */
window.webVitals = {};
function randomInRange(min, max) {
  return Math.random() * (max - min) + min;
}
window.webVitals.getCLS = function (cb) {
  setTimeout(() => cb({value: parseFloat(randomInRange(0, 0.25).toFixed(3)), name: 'CLS'}), 100);
};
window.webVitals.getLCP = function (cb) {
  setTimeout(() => cb({value: parseFloat(randomInRange(1, 5).toFixed(2)), name: 'LCP'}), 100);
};
window.webVitals.getFID = function (cb) {
  setTimeout(() => cb({value: Math.round(randomInRange(10, 300)), name: 'FID'}), 100);
};
window.webVitals.getTTFB = function (cb) {
  setTimeout(() => cb({value: parseFloat(randomInRange(0.1, 0.8).toFixed(2)), name: 'TTFB'}), 100);
};
